
SELECT DISTINCT
	public.t_dataset.dataset_id,
	public.t_dataset.dataset,
	public.t_dataset."comment",
	public.t_dataset.acq_time_start,
	public.t_instrument_name.instrument,
	public.t_requested_run.eus_proposal_id,
	concat(public.t_storage_path.url_https,
		public.t_dataset.folder_name) AS "data_folder_path",
	public.t_dataset_rating_name.dataset_rating
FROM
	public.t_dataset INNER JOIN
	public.t_instrument_name  ON public.t_dataset.instrument_id = public.t_instrument_name.instrument_id INNER JOIN
	public.t_requested_run ON public.t_dataset.dataset_id = public.t_requested_run.dataset_id INNER JOIN
	public.t_storage_path ON public.t_dataset.storage_path_id = public.t_storage_path.storage_path_id INNER JOIN
	public.t_dataset_rating_name ON public.t_dataset_rating_name.dataset_rating_id = public.t_dataset.dataset_rating_id
WHERE public.t_dataset.dataset_rating_id = 5 AND

	public.t_dataset.dataset_id IN(

